  // --- SOLID ARCHITECTURAL EDITORIAL THEME (ZERO GLASSMORPHISM) ---
  const isLight = uiTheme === 'editorial';
  const bgMain = isLight ? 'bg-[#F6F3EC] text-stone-900' : 'bg-[#121316] text-stone-100';
  const bgHeader = isLight ? 'bg-[#EFECE4] border-stone-300' : 'bg-[#181A1F] border-stone-800';
